namespace Light.ChatCommands;

[Harmony]
public class PatchManager
{
    public static bool IsHost(PlayerControl player) => AmongUsClient.Instance.AmHost;
    public static void SendLocalMessage(string msg)
    {
        var pc = PlayerControl.LocalPlayer;
        string orig = pc.name;
        pc.SetName("System");
        HudManager.Instance.Chat.AddChat(pc, msg);
        pc.SetName(orig);
    }
    public static bool SendNormalMessage(string msg)
    {
        PlayerControl.LocalPlayer.RpcSendChat(msg);
        return true;
    }
    public static bool OnSendChat(ChatController __instance)
    {
        bool isHost = IsHost(PlayerControl.LocalPlayer);
        string text = __instance.freeChatField.textArea.text.Trim();
        string raw = __instance.freeChatField.textArea.text;
        string[] parts = text.Split(' ', StringSplitOptions.RemoveEmptyEntries);
        if (parts.Length == 0) return true;
        string cmd = parts[0].ToLower();
        switch (cmd)
        {
            case "/test":
                if (!isHost) return false;
                SendLocalMessage("指令测试");
                __instance.freeChatField.Clear();
                return false;
            case "/suicide":
                RpcDefinitions.Suicide(PlayerControl.LocalPlayer);
                __instance.freeChatField.Clear();
                return false;
            case "/showchat":
                RpcDefinitions.ShowChat();
                __instance.freeChatField.Clear();
                return false;
            case "/hidechat":
                RpcDefinitions.HideChat();
                __instance.freeChatField.Clear();
                return false;
            case "t":
                SendLocalMessage("t-Complate");
                __instance.freeChatField.Clear();
                return false;
            case "/sr":
                try
                {
                    var gil = LightInDark.Game.GameManager.Instance.LocalPlayer;
                    LightLogger.Log(gil.ToString());
                    if (gil == null) return false;
                    gil.SetRole(RoleRegistry.Get<Caller>());
                    __instance.freeChatField.Clear();
                    return false;
                }
                catch(Exception ex)
                {
                    LightLogger.LogError($"设置角色失败:{ex.Message}");
                    __instance.freeChatField.Clear();
                    return false;
                }
            case "/sw":
                try
                {
                    HudUI.OpenButtonWindow("测试窗口"
                        ,new HudUI.ButtonOption("按钮1", () => SendLocalMessage("按钮1被点击"))
                        , new HudUI.ButtonOption("按钮2", () => SendLocalMessage("按钮2被点击"))
                        );
                    __instance.freeChatField.Clear();
                    return false;
                }
                catch(Exception ex)
                {
                    LightLogger.LogWarning($"window异常：{ex.Message}");
                    __instance.freeChatField.Clear();
                    return false;
                }
            case "/code":
                int i = AmongUsClient.Instance.GameId;
                string code = GameCode.IntToGameNameV2(i);
                SendLocalMessage($"当前房间码为:{code}");
                __instance.freeChatField.Clear();
                return false;
            case "/kick":
                try
                {
                    if (!isHost) return false;
                    if (parts.Length < 2)
                    {
                        SendLocalMessage("请指定要踢出的玩家ID");
                        __instance.freeChatField.Clear();
                        return false;
                    }
                    PlayerControl target = null;
                    string targetName = parts[1];
                    foreach (var p in PlayerControl.AllPlayerControls)
                        if (p.Data.PlayerName.Contains(targetName, StringComparison.OrdinalIgnoreCase)) { target = p; break; }
                    if (target == null)
                    {
                        SendLocalMessage("未找到指定玩家");
                        __instance.freeChatField.Clear();
                        return false;
                    }
                    string reason = parts.Length >= 3 ? string.Join(' ', parts.Skip(2)) : "无";
                    AmongUsEdited.KickPlayer(target.ToLIDPlayer(), PlayerControl.LocalPlayer.name, reason);
                    __instance.freeChatField.Clear();
                    return false;
                }
                catch(Exception ex)
                {
                    LightLogger.LogWarning($"踢人失败:{ex.Message}");
                    __instance.freeChatField.Clear();
                    return false;
                }
        }

        return true;
    }
}

using LightInDark.Roles;
using UnityEngine;

namespace LightInDark.Events
{
    // =====================================================================
    // 事件基础类型
    //
    // - Event: 标记接口（已有 IEvent）
    // - AbstractPlayerEvent: 持有 PlayerControl，支持 [OnlyMyPlayer] 等过滤
    // - 可取消事件: public bool IsCanceled { get; set; }（合作式取消，非抢占式）
    // - 内部构造函数：事件由框架构造，不由消费者创建
    // =====================================================================

    /// <summary>
    /// 玩家事件基类。
    /// 持有 PlayerControl，支持 [OnlyMyPlayer] / [OnlyLocalPlayer] 等过滤。
    /// </summary>
    public abstract class BasePlayerEvent : IEvent
    {
        public PlayerControl Player { get; init; }
        protected BasePlayerEvent(PlayerControl player) => Player = player;
        protected BasePlayerEvent() { }
    }

    /// <summary>
    /// 可取消事件基类。
    /// IsCanceled 为合作式：监听者设置后，后续监听者可读取。
    /// 调度器不会自动中断，由调用方检查 IsCanceled。
    /// </summary>
    public abstract class BaseCancelableEvent : IEvent
    {
        public bool IsCanceled { get; set; }
    }

    /// <summary>
    /// 可取消的玩家事件。
    /// </summary>
    public abstract class BaseCancelablePlayerEvent : BasePlayerEvent
    {
        public bool IsCanceled { get; set; }
        protected BaseCancelablePlayerEvent(PlayerControl player) : base(player) { }
        protected BaseCancelablePlayerEvent() { }
    }

    // =====================================================================
    // 游戏流程事件
    // =====================================================================

    /// <summary>游戏开始</summary>
    public class GameStartEvent : IEvent
    {
        public int PlayerCount { get; init; }
    }

    /// <summary>游戏结束</summary>
    public class GameEndEvent : IEvent
    {
        public bool CrewmatesWin { get; init; }
        public bool ImpostorsWin { get; init; }
        public string WinReason { get; init; } = "";
    }

    /// <summary>游戏即将结束（可阻止）</summary>
    public class GameTryEndEvent : BaseCancelableEvent
    {
        public bool CrewmatesWin { get; set; }
        public bool ImpostorsWin { get; set; }
        public string Reason { get; set; } = "";
    }

    /// <summary>自定义职业被设置到玩家</summary>
    public class RoleAssignedEvent : BasePlayerEvent
    {
        public DefinedRole Role { get; init; }
        public int[] Arguments { get; init; } = System.Array.Empty<int>();
        public RoleAssignedEvent() { }
        public RoleAssignedEvent(PlayerControl player, DefinedRole role, int[] arguments = null) : base(player) { Role = role; Arguments = arguments ?? System.Array.Empty<int>(); }
    }

    /// <summary>换职前（可阻止）</summary>
    public class PlayerTryToChangeRoleEvent : BaseCancelablePlayerEvent
    {
        public RuntimeRole OldRole { get; init; }
        public DefinedRole NewRole { get; init; }
        public PlayerTryToChangeRoleEvent() { }
